"""Synthetic EXE-like byte arrays for an end-to-end training/runtime smoke test."""

from __future__ import annotations

import csv
from hashlib import sha256
from pathlib import Path
from typing import Any

import yaml

from malweave.config import CONFIGS_DIR
from malweave.data.rands import BENIGN_HEADER, RANSOMWARE_ACTUAL_HEADER
from malweave.data.rands_training import Progress, RandsTrainingError, load_config, prepare_exe
from malweave.training.scratch import ScratchRequest, run_scratch


def synthetic_inputs(root: Path, *, per_class: int = 8) -> int:
    """Only printable, generated bytes; never a PE fixture or a real corpus sample."""
    metadata = root / "metadata"
    metadata.mkdir(parents=True, exist_ok=True)
    for label, name, header in [
        ("benign", "Benign.csv", BENIGN_HEADER),
        ("ransomware", "Ransomware.csv", RANSOMWARE_ACTUAL_HEADER),
    ]:
        with (metadata / name).open("w", newline="") as handle:
            writer = csv.writer(handle)
            writer.writerow(header)
            for index in range(per_class):
                content = f"SYNTHETIC {label} item {index}. ".encode() * (4 + index)
                source = sha256(f"synthetic source {label} {index}".encode()).hexdigest()
                path = root / "exe" / source[:2] / (source + ".bin")
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_bytes(content)
                row = [source, "0" * 40, "0" * 32, len(content), "exe", "x86", 0, 1.0]
                if label == "ransomware":
                    row.append("synthetic-family")
                writer.writerow([*row, 2026, "synthetic"])
    return per_class * 2


def smoke(root: Path, *, device: str = "cuda:0") -> dict[str, Any]:
    if root.exists():
        raise RandsTrainingError("Smoke work directory already exists; choose a fresh --work-dir.")
    root.mkdir(parents=True)
    config = load_config(CONFIGS_DIR / "experiments/rands-exe-scratch.yaml")
    config["experiment"]["name"] = "synthetic-scratch-smoke"
    config["data"]["expected_exe_files"] = synthetic_inputs(root / "inputs")
    config["tokenizer"].update(vocab_size=272, max_train_files=16, max_bytes_per_file=64)
    config["model"].update(
        max_tokens=32,
        architecture={
            "hidden_size": 16,
            "num_hidden_layers": 1,
            "state_size": 4,
            "expand": 2,
            "conv_kernel": 4,
            "hidden_dropout_prob": 0.0,
            "residual_in_fp32": True,
            "is_decoder": False,
            "bi_tie_directions": False,
            "bi_add_directions": True,
        },
    )
    config["training"].update(
        epochs=1,
        batch_size=2,
        gradient_accumulation_steps=1,
        precision="fp32",
        gradient_checkpointing=False,
    )
    config["runtime"].update(cpu_threads=1, dataloader_workers=0, checkpoint_updates=2)
    config_path = root / "config.yaml"
    config_path.write_text(yaml.safe_dump(config, sort_keys=False))
    with Progress() as progress:
        prepare_exe(root / "inputs", config_path, progress=progress)
    return run_scratch(
        ScratchRequest(config_path, root / "inputs", root / "runs", "smoke", device=device)
    )
